#!/usr/bin/env python3
"""Lists everything the simulator assumes without a source: the rows of RULES.md whose
confidence says "guess" and the constants in Constants.fs documented as a guess.
    python3 tools/rules/guesses.py        writes GUESSES.md
"""
import os, re

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..")
rules = open(os.path.join(root, "RULES.md"), encoding="utf-8").read().split("\n")
consts = open(os.path.join(root, "src", "PoEtry", "Constants.fs"), encoding="utf-8").read().split("\n")

out = ["# Open guesses", "",
       "Generated by `tools/rules/guesses.py` from RULES.md and `src/PoEtry/Constants.fs`. Do not edit.",
       "",
       "What the simulator assumes without a source in the game data, the wiki or an in-game",
       "observation. Each wants an in-game test or a data source; when one is found, change the",
       "confidence in RULES.md (and the comment in Constants.fs) and add a test.",
       "",
       "## Checking against a new game version",
       "",
       "1. Update the game, then `cd tools/gamefiles && npx pathofexile-dat` (tables) and",
       "   `tools/export/export.lua` (data/game).",
       "2. `dotnet run -c Release --project tests/PoEtry.Tests`: the data tests name every gem",
       "   value that moved.",
       "3. `dotnet fsi tools/census/census.fsx` and `tools/skills/ledger.fsx`: new stats and skill",
       "   types nothing reads yet.",
       "4. `dotnet fsi --optimize+ tools/skills/dossier.fsx`, then diff `dossiers.txt`: skills",
       "   whose description or behaviour changed.",
       "5. Go through the lists below; the wiki's version history of a skill says what changed.",
       ""]

section, rows = "", {}
for line in rules:
    if line.startswith("## "):
        section = line[3:].strip()
    elif line.startswith("|"):
        cells = [c.strip() for c in line.strip().strip("|").split(" | ")]
        if len(cells) >= 3 and "guess" in cells[-1].lower() and cells[0] not in ("Rule", "Mechanic"):
            rows.setdefault(section, []).append(cells)

total = sum(len(v) for v in rows.values())
out += [f"## Rules ({total})", ""]
for sec, items in rows.items():
    out += [f"### {sec}", "", "| Rule | Source, and what is guessed | Confidence |", "|---|---|---|"]
    for c in items:
        out.append(f"| {c[0]} | {c[-2]} | {c[-1]} |")
    out.append("")

found, doc = [], []
for line in consts:
    s = line.strip()
    if s.startswith("///"):
        doc.append(s[3:].strip())
    else:
        m = re.match(r"let\s+(\w+)\s*=\s*(.*)", s)
        text = " ".join(doc)
        if m and re.search(r"\bguess", text, re.I):
            found.append((m.group(1), m.group(2), text))
        if s:
            doc = []
out += [f"## Constants ({len(found)})", "", "| Constant | Value | What it stands for |", "|---|---|---|"]
for name, value, text in found:
    out.append(f"| `{name}` | `{value.replace('|', '/')}` | {text.replace('|', '/')} |")
out.append("")
open(os.path.join(root, "GUESSES.md"), "w", encoding="utf-8").write("\n".join(out))
print(f"{total} rules, {len(found)} constants")
